-- V108 tenant-pinned data residency evidence. No geographic region is assumed by the platform.
CREATE TABLE IF NOT EXISTS data_residency_policies(tenant_id text NOT NULL,version integer NOT NULL CHECK(version>=1),primary_region text NOT NULL,allowed_regions jsonb NOT NULL,definition_hash char(64) NOT NULL,configured_by_hash char(64) NOT NULL,configured_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,version));CREATE TABLE IF NOT EXISTS data_residency_attestations(tenant_id text NOT NULL,resource_type text NOT NULL,resource_id_hash char(64) NOT NULL,version integer NOT NULL CHECK(version>=1),policy_version integer NOT NULL,policy_hash char(64) NOT NULL,primary_region text NOT NULL,replica_regions jsonb NOT NULL,provider_evidence_hash char(64) NOT NULL,attested_by_hash char(64) NOT NULL,attested_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,resource_type,resource_id_hash,version));ALTER TABLE data_residency_policies ENABLE ROW LEVEL SECURITY;ALTER TABLE data_residency_policies FORCE ROW LEVEL SECURITY;ALTER TABLE data_residency_attestations ENABLE ROW LEVEL SECURITY;ALTER TABLE data_residency_attestations FORCE ROW LEVEL SECURITY;CREATE POLICY residency_policy_tenant ON data_residency_policies USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));CREATE POLICY residency_attestation_tenant ON data_residency_attestations USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));
